rocedure"},{"kind":"Reader''s note","owner":"procedure","text":"Some catalog course titles differ from the closed-list titles (e.g., ART C100, ENGL C101, ENGL C140, HIST C170 ''to 1877'' vs ''1876'', HIST C175 ''since 1865'' vs ''1876''); reviewer may wish to verify.","where":"Coastline Community College''s CourseLeaf reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"Total Units 60 is the degree total; the major total is ''Units Required for Major 18''. GE is ''Local General Education or CalGETC pattern'' and electives are ''Varies'', so open_elective_units is null.","where":"Coastline Community College''s CourseLeaf reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"The overview lists university majors (Art, English, etc.) rather than careers, so no careers were recorded.","where":"Coastline Community College''s CourseLeaf reading procedure"}],"map":{"checked_run":"census-20261011T162427Z-s3of4","host":null,"status":"none","text":"The weekly census found no published term-by-term program map on Coastline Community College''s site (census run census-20261011T162427Z-s3of4).","url":null},"v":1}'::jsonb from public.program_requirement_records r where r.college = 'Coastline Community College' and r.control_number = '18052' on conflict (college, control_number) do update set display = excluded.display;
