ere":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"The catalog title for ACC-66 is ''Governmental and Non-Profit Accounting''; the state file title is ''Non-Profit and Governmental Accounting''.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"CAT-3 and CIS-3 share the title ''Computer Applications for Business''. They may be cross-listed, but they are printed as separate options.","where":"Riverside City College''s CurriQunet META reading procedure"}],"map":{"checked_run":"census-20261004T152832Z-s4of4","host":null,"status":"none","text":"The weekly census found no published term-by-term program map on Riverside City College''s site (census run census-20261004T152832Z-s4of4).","url":null},"v":1}'::jsonb from public.program_requirement_records r where r.college = 'Riverside City College' and r.control_number = '04456' on conflict (college, control_number) do update set display = excluded.display;
