: 34.00 (28 required + 6 emphasis).","where":"Riverside City College''s CurriQunet META reading procedure"}],"map":{"checked_run":"census-20261004T152832Z-s4of4","host":null,"status":"none","text":"The weekly census found no published term-by-term program map on Riverside City College''s site (census run census-20261004T152832Z-s4of4).","url":null},"v":1}'::jsonb from public.program_requirement_records r where r.college = 'Riverside City College' and r.control_number = '31766' on conflict (college, control_number) do update set display = excluded.display;
