ce College","Madera College","Mt. San Jacinto College","Santa Ana College"],"credential":"AP Statistics"},{"colleges":["Modesto Junior College"],"credential":"Business Statistics"},{"colleges":["Modesto Junior College"],"credential":"Elementary Statistics"},{"colleges":["Ventura College"],"credential":"Elementary Statistics with Applications for Health Care Professionals"}],"credentials_n":5},"coci":{"current_ccn":"CCC000650087","listed":true,"program_ccn":"CCC000578633","status":"Inactive"},"identity":{"id":"MATH 110","kind":"C-ID","title":"Introduction to Statistics"},"ids":[{"id":"MATH 110","kind":"C-ID","title":"Introduction to Statistics"}],"title":"Statistics for the Behavioral Sciences"},"SOC-50":{"identity":{"id":"SOCI 120","kind":"C-ID","title":"Introduction to Research Methods"},"ids":[{"id":"SOCI 120","kind":"C-ID","title":"Introduction to Research Methods"}],"title":"Introduction to Social Research Methods"},"STAT-C1000":{"adopt":{"colleges_n":10,"credentials":[{"colleges":["Chaffey College","Coastline Community College","Glendale Community College","Los Angeles Pierce College","Madera College","Mt. San Jacinto College","Santa Ana College"],"credential":"AP Statistics"},{"colleges":["Modesto Junior College"],"credential":"Business Statistics"},{"colleges":["Modesto Junior College"],"credential":"Elementary Statistics"},{"colleges":["Ventura College"],"credential":"Elementary Statistics with Applications for Health Care Professionals"}],"credentials_n":5},"identity":{"id":"STAT C1000","kind":"CCN","title":"Introduction to Statistics"},"ids":[{"id":"STAT C1000","kind":"CCN","title":"Introduction to Statistics"},{"id":"MATH 110","kind":"C-ID","title":"Introduction to Statistics"}],"title":"Introduction to Statistics"},"STAT-C1000H":{"adopt":{"colleges_n":10,"credentials":[{"colleges":["Chaffey College","Coastline Community College","Glendale Community College","Los Angeles Pierce College","Madera College","Mt. San Jacinto College","Santa Ana College"],"credential":"AP Statistics"},{"colleges":["Modesto Junior College"],"credential":"Business Statistics"},{"colleges":["Modesto Junior College"],"credential":"Elementary Statistics"},{"colleges":["Ventura College"],"credential":"Elementary Statistics with Applications for Health Care Professionals"}],"credentials_n":5},"identity":{"id":"STAT C1000H","kind":"CCN","title":"Introduction to Statistics - Honors"},"ids":[{"id":"STAT C1000H","kind":"CCN","title":"Introduction to Statistics - Honors"},{"id":"MATH 110","kind":"C-ID","title":"Introduction to Statistics"}],"title":"Introduction to Statistics - Honors"}},"figure":{"measure":"units","path":null,"path_picks":[],"path_why":"No pathway map has been read for this program.","picks":[],"total":{"max":19,"min":18},"up_to":0.0},"gaps":[{"kind":"Catalog and state file differ","owner":"college","text":"The catalog prints ETS-28, HIST-29 for this program; the state''s Program Course File does not list them.","where":"Riverside City College''s program record in the state''s curriculum inventory"},{"kind":"Check not met","owner":"procedure","text":"The blocks add to 12-13 units; the catalog prints 18-19 units.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"The page prints two headings for this degree: ''Social Justice Studies: General - Associate in Arts for Transfer (ADT) - AA1004 (CalGETC)'' and ''... - AAA1004 (CalGETC)'', followed by ''Social Justice Studies - Associate in Arts for Transfer (ADT)''. All appear to refer to the same single program section.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"Required Courses heading states ''Units: 9.00'' but only one ''Select one of the following'' list (3.00 units) is printed under it. The program total of 18.00-19.00 equals 9 + 9-10, so the required section may be cut off or mislabelled; recorded only the printed select-one list (stated 3). Reviewer should check the source.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"Elective Courses rule is ''Select 3 courses from at least two areas'' (9.00-10.00 units). Recorded as one choose_courses block of 3. The two-area constraint is not expressible in the schema. Area membership: Area 1 - History or Government (HIST-34 through ETS-23/POLS-23); Area 2 - Arts and Humanities (ENGL-18 through PHI-34); Area 3 - Social Science (ANT-4/ETS-27 through SOC-50); Area 4 - Qualitative Reasoning and Research Methods (STAT-C1000/STAT-C1000H/PSYC-48/SOC-48).","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"Area unit figures printed (Area 1 6.00, Area 2 36.00, Area 3 12.00, Area 4 4.00) do not appear to be selection minimums; they were not recorded as block totals.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"HIST-34 is printed twice in Area 1; listed once.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"The catalog prints history courses as ''HIST-'' while the closed list uses ''HIS''. HIST-14, HIST-15, HIST-28, HIST-31, HIST-34 and HIST-44 were treated as the closed-list HIS courses (catalog_addition false). HIST-29 has no HIS 29 in the closed list, so it is marked as an addition.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"Catalog additions not in the closed list: ETS-28, HIST-29, ENGL-25 and SOC-48.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"PSYC-48 is matched to closed-list ''PSYC48'', for which the state file stores no units; the catalog prints 4.00.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"ETS-1 appears both in the Required Courses select-one list and in Area 2 of the electives; it is recorded in both blocks.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"ETS-8 is titled ''Introduction to Black Feminism and Womanism'' in the catalog, versus ''Introduction to Black Feminism'' in the closed list.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"The program learning outcomes are printed once for the program, and this award shares them.","where":"Riverside City College''s CurriQunet META reading procedure"},{"kind":"Reader''s note","owner":"procedure","text":"Degree requires 60 CSU-transferable units with Cal-GETC and minimum 2.0 GPA; major courses need a grade of C or better (or P).","where":"Riverside City College''s CurriQunet META reading procedure"}],"map":{"checked_run":"census-20261004T152832Z-s4of4","host":null,"status":"none","text":"The weekly census found no published term-by-term program map on Riverside City College''s site (census run census-20261004T152832Z-s4of4).","url":null},"v":1}'::jsonb from public.program_requirement_records r where r.college = 'Riverside City College' and r.control_number = '41749' on conflict (college, control_number) do update set display = excluded.display;
